  switch_to_login: {sq:'Keni tashmë llogari? Hyni', sr:'Već imate nalog? Prijavite se', tr:'Zaten hesabınız var mı? Giriş Yapın', en:'Already have an account? Log in', de:'Bereits ein Konto? Anmelden', fr:'Déjà un compte ? Connectez-vous', it:'Hai già un account? Accedi', bs:'Već imate nalog? Prijavite se', el:'Έχετε ήδη λογαριασμό; Συνδεθείτε', ru:'Уже есть аккаунт? Войдите'},
