  toast_user_not_found: {sq:'Nuk u gjet përdorues me këtë email. Ju lutemi regjistrohuni.', sr:'Korisnik sa ovim email-om nije pronađen. Molimo registrujte se.', tr:'Bu e-posta ile kayıtlı kullanıcı bulunamadı. Lütfen kayıt olun.', en:'No user found with this email. Please register.', de:'Kein Benutzer mit dieser E-Mail gefunden. Bitte registrieren.', fr:'Aucun utilisateur trouvé avec cet e-mail. Veuillez vous inscrire.', it:'Nessun utente trovato con questa email. Registrati.', bs:'Korisnik sa ovim email-om nije pronađen. Molimo registrujte se.', el:'Δεν βρέθηκε χρήστης με αυτό το email. Παρακαλώ εγγραφείτε.', ru:'Пользователь с такой почтой не найден. Пожалуйста, зарегистрируйтесь.'},
  toast_passwords_mismatch: {sq:'Fjalëkalimet nuk përputhen.', sr:'Lozinke se ne podudaraju.', tr:'Şifreler eşleşmiyor.', en:'Passwords do not match.', de:'Passwörter stimmen nicht überein.', fr:'Les mots de passe ne correspondent pas.', it:'Le password non corrispondono.', bs:'Lozinke se ne podudaraju.', el:'Οι κωδικοί δεν ταιριάζουν.', ru:'Пароли не совпадают.'},
  toast_password_short: {sq:'Fjalëkalimi duhet të ketë të paktën 6 karaktere.', sr:'Lozinka mora imati najmanje 6 karaktera.', tr:'Şifre en az 6 karakter olmalıdır.', en:'Password must be at least 6 characters.', de:'Das Passwort muss mindestens 6 Zeichen lang sein.', fr:'Le mot de passe doit contenir au moins 6 caractères.', it:'La password deve contenere almeno 6 caratteri.', bs:'Lozinka mora imati najmanje 6 karaktera.', el:'Ο κωδικός πρέπει να έχει τουλάχιστον 6 χαρακτήρες.', ru:'Пароль должен содержать не менее 6 символов.'},
  toast_fill_required: {sq:'Ju lutemi plotësoni fushat e detyrueshme.', sr:'Molimo popunite obavezna polja.', tr:'Lütfen zorunlu alanları doldurun.', en:'Please fill in the required fields.', de:'Bitte füllen Sie die Pflichtfelder aus.', fr:'Veuillez remplir les champs obligatoires.', it:'Compila i campi obbligatori.', bs:'Molimo popunite obavezna polja.', el:'Συμπληρώστε τα υποχρεωτικά πεδία.', ru:'Заполните обязательные поля.'},
  toast_already_registered: {sq:'Ky email është regjistruar tashmë. Ju lutemi hyni.', sr:'Ovaj email je već registrovan. Molimo prijavite se.', tr:'Bu e-posta zaten kayıtlı. Lütfen giriş yapın.', en:'This email is already registered. Please log in.', de:'Diese E-Mail ist bereits registriert. Bitte anmelden.', fr:'Cet e-mail est déjà enregistré. Veuillez vous connecter.', it:'Questa email è già registrata. Accedi.', bs:'Ovaj email je već registrovan. Molimo prijavite se.', el:'Αυτό το email είναι ήδη καταχωρημένο. Παρακαλώ συνδεθείτε.', ru:'Эта почта уже зарегистрирована. Пожалуйста, войдите.'},

