  detail_demo_note: {sq:'Shënim: ky prototip nuk ka sistem real mesazhesh.', sr:'Napomena: ovaj prototip nema pravi sistem poruka.', tr:'Not: bu prototipte gerçek mesajlaşma sistemi yoktur.', en:'Note: this prototype has no real messaging system.', de:'Hinweis: Dieser Prototyp hat kein echtes Nachrichtensystem.', fr:'Remarque : ce prototype n\'a pas de vrai système de messagerie.', it:'Nota: questo prototipo non ha un vero sistema di messaggistica.', bs:'Napomena: ovaj prototip nema pravi sistem poruka.', el:'Σημείωση: αυτό το πρωτότυπο δεν έχει πραγματικό σύστημα μηνυμάτων.', ru:'Примечание: в этом прототипе нет настоящей системы сообщений.'},
  marked_on_map: {sq:'Vendndodhje e shënuar në hartë', sr:'Lokacija označena na mapi', tr:'Haritada işaretli konum', en:'Location marked on map', de:'Standort auf Karte markiert', fr:'Emplacement indiqué sur la carte', it:'Posizione segnata sulla mappa', bs:'Lokacija označena na mapi', el:'Τοποθεσία σημειωμένη στον χάρτη', ru:'Местоположение отмечено на карте'},
