export function t(key: keyof typeof UI, lang: LangCode): string {
  const entry = UI[key] as Record<string, string> | undefined;
  if (!entry) return key;
  return entry[lang] || entry.en || key;
}
export function catName(id: string, lang: LangCode): string {
  const c = CAT_I18N[id];
  return c.name[lang] || c.name.en;
}
export function catDesc(id: string, lang: LangCode): string {
  const c = CAT_I18N[id];
  return c.desc[lang] || c.desc.en;
}
export function subName(id: string, lang: LangCode): string {
  const s = SUB_I18N[id];
  return s[lang] || s.en;
}
